package com.singtel.promotionservice;
import jakarta.persistence.*;import java.util.*;import java.time.Instant;import java.math.BigDecimal;
@Entity @Table(name="promotions",uniqueConstraints=@UniqueConstraint(name="promotion_code_unique",columnNames="code"),indexes=@Index(name="promotion_status_dates",columnList="status,startAt,endAt"))public class Promotion{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,length=30)public String code;@Column(nullable=false,length=120)public String name;@Column(nullable=false,length=2000)public String description;@Enumerated(EnumType.STRING)@Column(nullable=false)public Lifecycle.Status status=Lifecycle.Status.DRAFT;public String discountType;@Column(precision=19,scale=4)public BigDecimal discountValue;@Column(length=3)public String currency="SGD";@Column(nullable=false)public Instant startAt;@Column(nullable=false)public Instant endAt;public long totalRedemptionLimit;public int perCustomerLimit;@Column(precision=19,scale=2)public BigDecimal budgetLimit;@Column(nullable=false)public UUID ruleVersionId;public String segment;public String channel;public String createdBy;public String approvedBy;@Version public long version;public Instant createdAt=Instant.now();public Instant updatedAt=Instant.now();@Column(columnDefinition="text")public String historyJson="[]";public Promotion(){}}
